#!/usr/bin/env bash
set -euo pipefail
# apply_v25.sh - Ora Ahora v25 (1.0.15+16)
# 1) Notificaciones EXACTAS (antes inexactas -> no llegaban en Xiaomi)
# 2) Overlay: mas oraciones de respaldo + notificacion mas humana
echo "Aplicando cambios v25..."
mkdir -p "$(dirname 'lib/services/notification_service.dart')"
base64 -d > 'lib/services/notification_service.dart' <<'B64_dd9f0a8a'

B64_dd9f0a8a
python3 - <<'PY'
import io, re
# --- 1) Expandir FALLBACK en PrayerGateActivity.kt ---
fa = "android/app/src/main/kotlin/com/oraahora/app/PrayerGateActivity.kt"
s = open(fa, encoding="utf-8").read()
anchor = '"Dios, dame un minuto contigo antes que a la pantalla. Solo un minuto. Amén.",'
extra = "\n".join([
 '        "Padre, sé que vine por costumbre. Ayúdame a decidir con calma. Amén.",',
 '        "Señor, calma mi prisa. No necesito llenar cada silencio con el celular. Amén.",',
 '        "Dios, gracias por este alto. Respiro, y me acuerdo de que estás aquí. Amén.",',
 '        "Padre, que este momento sea mío otra vez, y no de la pantalla. Amén.",',
 '        "Jesús, antes de scrollear, quiero mirarte a ti primero. Amén.",',
 '        "Señor, cuida mi mente de lo que estoy por ver. Guárdame. Amén.",',
 '        "Dios, si abro esto, que sea con paz y no por ansiedad. Amén.",',
 '        "Padre, un respiro contigo vale más que mil videos. Gracias. Amén.",',
 '        "Señor, ayúdame a soltar el teléfono cuando toque soltarlo. Amén.",',
 '        "Jesús, ocupa tú el lugar que le doy a esta pantalla. Amén.",',
])
if anchor in s and "quiero mirarte a ti primero" not in s:
    s = s.replace(anchor, anchor + "\n" + extra, 1)
    open(fa, "w", encoding="utf-8").write(s)
    print("FALLBACK expandido OK")
else:
    print("FALLBACK: anchor no encontrado o ya aplicado")

# --- 2) Notificacion del FG service mas humana ---
fs = "android/app/src/main/kotlin/com/oraahora/app/PrayerGateForegroundService.kt"
s2 = open(fs, encoding="utf-8").read()
old = '.setContentText("Pausa y Ora está activa, cuidando tu atención \U0001f64f")'
new = '.setContentText("Antes de abrir una app, respira y ora un momento \U0001f64f")'
if old in s2:
    s2 = s2.replace(old, new, 1)
    open(fs, "w", encoding="utf-8").write(s2)
    print("Notificacion FG actualizada OK")
else:
    print("Notificacion FG: texto no encontrado (revisar)")
PY
echo "===V25_FILES_APPLIED==="
